          onClick={e => e.stopPropagation()}
        >
          {/* Header */}
          <div className="p-8 border-b border-white/5 flex items-center justify-between bg-white/[0.02]">
            <div>
              <span className={`text-[10px] font-black uppercase tracking-widest block mb-1 ${project.status === ProjectStatus.MAIN_PROJECT ? 'text-amber-400' : 'text-blue-400'}`}>{project.status}</span>
              <h3 className="text-2xl font-bold text-white">{project.title}</h3>
            </div>
            <button 
              onClick={onClose} 
              className="p-3 rounded-2xl bg-white/5 border border-white/10 text-slate-400 hover:text-white transition-all"
            >
              <X size={20} />
            </button>
          </div>

          <div className="overflow-y-auto p-8 space-y-8 custom-scrollbar">
            <div className="space-y-6">
