                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Outcome</h4>
                <p className="text-slate-200 text-sm leading-relaxed font-medium">{project.outcome}</p>
              </div>

              <div className="space-y-3">
