              </div>

              {project.subLinks && project.subLinks.length > 0 && (
                <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Sparkles size={12} className={project.status === ProjectStatus.MAIN_PROJECT ? 'text-amber-400' : 'text-blue-400'} /> Assets & Links
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {project.subLinks.map((sub, i) => (
                      <a 
                        key={i} 
                        href={sub.url} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="flex flex-col p-4 rounded-xl bg-white/5 border border-white/5 hover:border-white/10 transition-all group/sub"
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="text-[11px] font-bold text-slate-300 truncate pr-2">{sub.name}</span>
                          <ArrowUpRight size={12} className="text-slate-500 group-hover/sub:text-white transition-colors" />
                        </div>
                        {sub.description && (
                          <span className="text-[9px] text-slate-500 mt-1 font-medium italic">{sub.description}</span>
                        )}
                      </a>
                    ))}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-8 pt-6 border-t border-white/5">
                <div>
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Role</h4>
                  <div className="flex items-center gap-3 text-slate-300 text-[13px] font-bold">
                    <div className={`p-1.5 rounded-lg bg-opacity-10 ${project.status === ProjectStatus.MAIN_PROJECT ? 'bg-amber-500' : 'bg-blue-500'}`}>
                      <User size={12} className={project.status === ProjectStatus.MAIN_PROJECT ? 'text-amber-500' : 'text-blue-500'} />
                    </div>
                    {project.role}
                  </div>
                </div>
                <div>
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Stack</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {project.tags.map(tag => (
                      <span key={tag} className="px-1.5 py-0.5 rounded-md bg-white/5 border border-white/10 text-[8px] text-slate-500 uppercase font-black">{tag}</span>
                    ))}
                  </div>
