              </div>
            </div>
          </div>

          <div className="p-8 border-t border-white/5 bg-white/[0.02]">
            {project.id === 'ai-voice-agent' ? (
              <div className="w-full py-4 rounded-2xl bg-white/5 text-slate-500 font-bold text-[11px] text-center border border-white/10 uppercase tracking-[0.2em]">
                Coming Soon
              </div>
            ) : project.isPrivate ? (
              <div className="w-full py-4 rounded-2xl bg-slate-800/50 text-slate-500 font-bold text-[11px] uppercase tracking-[0.2em] text-center border border-white/5 flex items-center justify-center gap-2">
                Restricted <Lock size={14} />
              </div>
            ) : project.link ? (
              <a 
                href={project.link} 
                target="_blank" 
                rel="noopener noreferrer" 
                className={`w-full py-4 rounded-2xl font-bold text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-2 transition-all shadow-xl ${project.status === ProjectStatus.MAIN_PROJECT ? 'bg-amber-600 text-white hover:bg-amber-700 shadow-amber-900/40' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-900/40'}`}
              >
                Visit Site <ExternalLink size={14} />
              </a>
            ) : (
              <div className="w-full py-4 rounded-2xl bg-white/5 text-slate-600 font-bold text-[11px] text-center border border-white/10 uppercase tracking-[0.2em]">
                Deployment Pending
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </>
