        <div>
          {project.id === 'ai-voice-agent' ? (
            <span className="text-[9px] text-slate-600 uppercase font-bold tracking-tight">Coming Soon</span>
          ) : project.isPrivate ? (
            <div className="flex items-center gap-1 text-[9px] text-slate-600 uppercase font-bold tracking-tight">
              <Lock size={10} /> Restricted
            </div>
          ) : (
            <div className={`px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest flex items-center gap-1.5 transition-colors shadow-lg ${project.status === ProjectStatus.MAIN_PROJECT ? 'bg-amber-600 text-white hover:bg-amber-500 shadow-amber-900/40' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/20'}`}>
